import{_ as e,c as t,o as s,ah as p}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"巽下乾上 姤：","description":"京氏易傳 - 巽下乾上 姤：","frontmatter":{"title":"巽下乾上 姤：","description":"京氏易傳 - 巽下乾上 姤："},"headers":[],"relativePath":"classics/jingshi/003.md","filePath":"classics/jingshi/003.md"}'),i={name:"classics/jingshi/003.md"};function r(n,a,c,_,o,l){return s(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="巽下乾上-姤" tabindex="-1">巽下乾上 姤： <a class="header-anchor" href="#巽下乾上-姤" aria-label="Permalink to “巽下乾上 姤：”">​</a></h1><p>陰爻用事。金木互體，天下風行曰姤。姤，遇也。《易》曰：“陰遇陽。”【一陰初生，陽氣猶盛，陰未為敵。】與巽為飛伏，元士居世。【辛丑土，甲子水。】尊就卑，【子孫與父母相代位。】定吉凶，只取一爻之象。【多以少為貴。】九四諸侯堅剛在上，陰氣處下。《易》雲：“繫於金柅。”</p><p>巽積陰入陽，辛壬降內外象，建庚午至乙亥。【芒種，小雪。】積算起乙亥水，至丙戌土，（虎易注：丙戌土疑為甲戌土之誤。）週而復始。【災福之兆，生乎五行升降也。】</p><p>五星從位起太白，【太白在西，居金位。】井宿從位入辛丑，【辛丑入土，元土臨母也。】（虎易注：元土當為元士之誤。）</p><p>建午起坤宮初六爻。《易》雲：“履霜堅冰至。”建亥，龍戰於野。【戌亥是乾之位。乾伏本位必戰，積陰之地猶盛，故戰。】</p><p>配於人事：為腹，為母，【坤順，容於物。】於類為馬。《易》雲：“行地無疆。”【此釋一爻配坤象，本體是乾巽，今贊一爻起陰，假坤象言之。】</p><p>內巽為風，乾為天；天下有風行，君子以號令告四方。【巽，入也。風入於坤，皆動也。故知天下有風動其物也。】</p><p>天風氣象三十六候。【三十六候節氣，降大風象。】木入金為始，【金納木也。】陰不能制於陽，附於金柅。《易》之“柔道牽”也。</p><p>五行升降，以時消息，陰蕩降入遁。【天山遁卦。】</p>',9)])])}const m=e(i,[["render",r]]);export{h as __pageData,m as default};
